211	    /**
212	     * Normalizes a telephone number by stripping every non-digit character and requiring the
213	     * result to be exactly 10 digits. The normalized 10-digit value is what gets stored and
214	     * returned.
215	     *
216	     * @param telephone the raw telephone value supplied by the client
217	     * @return the normalized 10-digit telephone number
218	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value does not
219	     *                                 contain exactly 10 digits after stripping non-digit characters
220	     */
221	    private static String normalizeTelephone(String telephone) {
222	        String digits = stripNonDigits(telephone);
223	        if (digits.length() != 10) {
224	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
225	                "telephone must contain exactly 10 digits after removing non-digit characters");
226	        }
227	        return digits;
228	    }
229	
230	    /**
231	     * Strips every non-digit character from the given value, returning "" for {@code null}. This is
232	     * the shared comparison rule used both when normalizing a submitted telephone and when comparing
233	     * against already-stored telephones.
234	     *
235	     * @param telephone the raw telephone value, possibly {@code null}
236	     * @return the value with all non-digit characters removed
237	     */
238	    private static String stripNonDigits(String telephone) {
239	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
240	    }
241	
242	    /**
243	     * Determines whether the given normalized telephone is already used by any owner other than the
244	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on create).
245	     * Stored telephones are normalized the same way before comparison so that differently formatted
246	     * values representing the same number are treated as duplicates.
247	     *
248	     * @param normalizedTelephone the already-normalized telephone to look for
249	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
250	     * @return {@code true} if another owner already uses the telephone
251	     */
252	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
253	        for (Owner existing : this.clinicService.findAllOwners()) {
254	            if (excludeId != null && excludeId.equals(existing.getId())) {
255	                continue;
256	            }
257	            if (normalizedTelephone.equals(stripNonDigits(existing.getTelephone()))) {
258	                return true;
259	            }
260	        }
261	        return false;
262	    }
